#!/usr/bin/env python3
"""Finite deterministic Worker payload for a disposable Rex-owned block."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import tempfile
from pathlib import Path


CHANGE = "Acceptance fixture change generated by deterministic_agent.py.\n"


def atomic_json(path: Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, name = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    temporary = Path(name)
    try:
        os.fchmod(fd, 0o600)
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            json.dump(value, stream, sort_keys=True)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--worktree", required=True, type=Path)
    parser.add_argument("--receipt", required=True, type=Path)
    parser.add_argument("--ticket-id", default="fixture-ticket-1")
    args = parser.parse_args()

    worktree = args.worktree.expanduser().resolve(strict=True)
    if not (worktree / ".git").exists():
        parser.error("--worktree must be an initialized disposable Git working tree")
    target = worktree / "src" / "acceptance-fixture.txt"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(CHANGE, encoding="utf-8")
    digest = hashlib.sha256(CHANGE.encode("utf-8")).hexdigest()
    atomic_json(args.receipt.expanduser().absolute(), {
        "schema_version": 1,
        "role": "worker",
        "ticket_id": args.ticket_id,
        "worktree": os.fspath(worktree),
        "changed_path": "src/acceptance-fixture.txt",
        "content_sha256": digest,
        "outcome": "completed",
    })
    print(json.dumps({"outcome": "completed", "changed_path": "src/acceptance-fixture.txt", "content_sha256": digest}, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
